def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opps = []
    prev_bids = []
    affordable_prev_bids = []
    urgent_opp_count = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opps.append(opp)
            if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
                urgent_opp_count += 1
            prev = opp.get('previous_trace', {})
            if prev:
                bid = prev.get('bid')
                if bid is not None:
                    bid = float(bid)
                    prev_bids.append(bid)
                    if opp.get('budget', 0) >= bid:
                        affordable_prev_bids.append(bid)

    if not alive_opps:
        return float(min(budget, 20.0))

    units = int(supply // WATER_REQ)
    if units < 1:
        units = 1

    high_supply = supply >= 24
    medium_supply = supply >= 20
    tight_supply = units <= 1 or supply <= 18

    highest_prev = max(prev_bids) if prev_bids else 0.0
    highest_affordable_prev = max(affordable_prev_bids) if affordable_prev_bids else highest_prev

    danger = 0
    if hp <= 2:
        danger += 3
    elif hp <= 4:
        danger += 2
    elif hp <= 6:
        danger += 1

    if no_water >= 2:
        danger += 3
    elif no_water >= 1:
        danger += 2

    if day >= 8:
        danger += 1

    if tight_supply:
        danger += 1
    elif high_supply:
        danger -= 1

    if danger >= 6:
        bid = max(0.92 * DAILY_SALARY, highest_affordable_prev + 2.0)
    elif danger >= 4:
        bid = max(0.78 * DAILY_SALARY, highest_affordable_prev + 1.0)
    elif danger >= 2:
        if tight_supply:
            bid = max(0.58 * DAILY_SALARY, highest_affordable_prev * 0.72)
        else:
            bid = 0.42 * DAILY_SALARY
    else:
        if high_supply:
            bid = 0.18 * DAILY_SALARY
        elif medium_supply:
            bid = 0.26 * DAILY_SALARY
        else:
            bid = 0.34 * DAILY_SALARY

    if urgent_opp_count >= 2 and danger <= 2:
        bid *= 0.85

    if highest_prev >= 130 and danger <= 2:
        bid = min(bid, 0.32 * DAILY_SALARY)

    reserve = 0.0
    if hp <= 4 or no_water >= 1:
        reserve = 0.0
    else:
        remaining_days = max(0, 10 - day)
        reserve = min(budget * 0.35, remaining_days * 8.0)

    bid = min(bid, max(0.0, budget - reserve))
    bid = min(bid, budget)

    if hp <= 2 or no_water >= 2:
        bid = max(bid, min(budget, 0.9 * DAILY_SALARY))

    if bid < 0:
        bid = 0.0

    return float(round(bid, 2))

