        return min(my_status['budget'], max(avg_prev * 1.1, 70.0))
    return min(my_status['budget'], max(40.0, avg_prev * 0.4))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.4)

    # Extract yesterday's bids from opponents' previous_trace
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    # Base strategy: safe bid around 45% of salary
    base_bid = DAILY_SALARY * 0.45

    # Emergency threshold: if HP low, we must win water
    if my_status['hp'] <= 2:
        # Need to win at any reasonable cost
        if yesterday_bids:
            highest_prev = max(yesterday_bids)
            # Outbid the highest yesterday by a small margin, but not exceed budget
            return min(my_status['budget'], highest_prev + 2.0)
        else:
            return min(my_status['budget'], DAILY_SALARY * 0.85)

    # Normal situation: relatively healthy
    if my_status['hp'] > 5:
        # Can afford to bid low, save budget
        if yesterday_bids:
            # If many high bids yesterday, opponents might be weak today
            tough_threshold = DAILY_SALARY * 0.8
            high_bids = [b for b in yesterday_bids if b >= tough_threshold]
            if len(high_bids) >= 2:
                # Opponents are wasting budget; we can bid very low
                return min(my_status['budget'], base_bid * 0.6)
            else:
                # Moderate competition
                return min(my_status['budget'], base_bid)
        else:
            return min(my_status['budget'], base_bid)
    else:
        # Moderate HP (3-5): need to secure water but not overspend
        if yesterday_bids:
            highest_prev = max(yesterday_bids)
            # Bid slightly above median of yesterday's bids if we must win
            median_bid = sorted(yesterday_bids)[int(len(yesterday_bids)//2)] if len(yesterday_bids)>=2 else yesterday_bids[0]
            target_bid = max(base_bid, median_bid * 0.9)
            return min(my_status['budget'], target_bid)
        else:
            return min(my_status['budget'], base_bid * 1.1)
